package com.cryptoloan.contract.adapters.out;import com.cryptoloan.contract.domain.port.out.ContractPorts.DocumentStorage;import java.nio.file.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;@Component class LocalDocumentStorageAdapter implements DocumentStorage{private final Path root;LocalDocumentStorageAdapter(@Value("${cryptoloan.documents.directory}")String root){this.root=Path.of(root).toAbsolutePath().normalize();}public String store(Long id,byte[] content){try{Files.createDirectories(root);Path target=root.resolve("loan-"+id+".txt").normalize();if(!target.startsWith(root))throw new SecurityException("Chemin invalide");Files.write(target,content,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING);return target.getFileName().toString();}catch(Exception e){throw new IllegalStateException("Impossible de stocker le contrat",e);}}public byte[] load(String reference){try{Path target=root.resolve(reference).normalize();if(!target.startsWith(root))throw new SecurityException("Chemin invalide");return Files.readAllBytes(target);}catch(Exception e){throw new IllegalStateException("Impossible de lire le contrat",e);}}}

